-- SOMENTE LOCAL. Catalogo, constraints e RLS; todas as fixtures sofrem rollback.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();

select has_table('public','digital_channels','Tabela de canais existe');
