select is(has_column_privilege('authenticated','public.digital_channels','updated_at','UPDATE'),false,'UPDATE de updated_at');

select col_is_pk('public','digital_channels','id','PK somente id');
select is((select count(*) from pg_constraint where conrelid='public.digital_channels'::regclass and contype='u'),0::bigint,'Sem UNIQUE artificial');
select is((select count(*) from pg_constraint where conrelid='public.digital_channels'::regclass and contype='c'),2::bigint,'Dois CHECKs');
select is((select array_agg(conname::text order by conname) from pg_constraint where conrelid='public.digital_channels'::regclass and contype='c'),array['digital_channels_type_check','digital_channels_url_check'],'CHECKs esperados');
select is((select count(*) from pg_constraint where conrelid='public.digital_channels'::regclass and contype='f'),2::bigint,'Duas FKs');
select is((select pg_get_constraintdef(oid) from pg_constraint where conrelid='public.digital_channels'::regclass and conname='digital_channels_organization_id_fkey'),'FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE RESTRICT','FK direta protege inclusive institucional');
select is((select pg_get_constraintdef(oid) from pg_constraint where conrelid='public.digital_channels'::regclass and conname='digital_channels_organization_location_fkey'),'FOREIGN KEY (organization_id, location_id) REFERENCES locations(organization_id, id) ON DELETE RESTRICT','FK composta usa o par existente');
select ok((select bool_and(confmatchtype='s' and confdeltype='r' and confupdtype='a' and not condeferrable and convalidated) from pg_constraint where conrelid='public.digital_channels'::regclass and contype='f'),'FKs MATCH SIMPLE, DELETE RESTRICT, UPDATE NO ACTION, imediatas e validadas');
select is((select count(*) from pg_index where indrelid='public.digital_channels'::regclass),2::bigint,'Somente PK e indice composto');
select is((select indexdef from pg_indexes where schemaname='public' and indexname='digital_channels_organization_location_idx'),'CREATE INDEX digital_channels_organization_location_idx ON public.digital_channels USING btree (organization_id, location_id)','Indice composto nao unico na ordem aprovada');
select ok((select relrowsecurity from pg_class where oid='public.digital_channels'::regclass),'RLS habilitada');
select is((select array_agg(policyname::text order by policyname) from pg_policies where schemaname='public' and tablename='digital_channels'),array['digital_channels_insert_admin','digital_channels_select_member_or_admin','digital_channels_update_admin'],'Exatamente tres policies');
