select ok((select cmd='SELECT' and qual is not null and with_check is null from pg_policies where schemaname='public' and policyname='digital_channels_select_member_or_admin'),'SELECT tem USING');
select ok((select cmd='INSERT' and qual is null and with_check is not null from pg_policies where schemaname='public' and policyname='digital_channels_insert_admin'),'INSERT tem WITH CHECK');
select ok((select cmd='UPDATE' and qual is not null and with_check is not null from pg_policies where schemaname='public' and policyname='digital_channels_update_admin'),'UPDATE tem USING e WITH CHECK');
select ok(has_table_privilege('authenticated','public.digital_channels','SELECT'),'SELECT concedido');
select ok(not has_table_privilege('authenticated','public.digital_channels','INSERT'),'Sem INSERT amplo para authenticated');
select ok(not has_table_privilege('authenticated','public.digital_channels','UPDATE'),'Sem UPDATE amplo para authenticated');
select ok(not has_table_privilege('authenticated','public.digital_channels','DELETE'),'Sem DELETE amplo para authenticated');
