select ok(not has_table_privilege('authenticated','public.digital_channels','REFERENCES'),'Sem REFERENCES amplo para authenticated');
select ok(not has_table_privilege('authenticated','public.digital_channels','TRIGGER'),'Sem TRIGGER amplo para authenticated');
