select ok(not has_table_privilege('anon','public.digital_channels','TRUNCATE'),'Sem TRUNCATE amplo para anon');
select ok(not has_table_privilege('anon','public.digital_channels','REFERENCES'),'Sem REFERENCES amplo para anon');
select ok(not has_table_privilege('anon','public.digital_channels','TRIGGER'),'Sem TRIGGER amplo para anon');
select ok(not has_table_privilege('anon','public.digital_channels','SELECT'),'Sem SELECT amplo para anon');
select ok(not exists(select 1 from pg_class c cross join lateral aclexplode(c.relacl) a where c.oid='public.digital_channels'::regclass and a.grantee=0),'PUBLIC sem grants de tabela');
select ok(not exists(select 1 from pg_attribute c cross join lateral aclexplode(c.attacl) a where c.attrelid='public.digital_channels'::regclass and a.grantee in (0,(select oid from pg_roles where rolname='anon'))),'PUBLIC/anon sem grants de coluna');
select is((select count(*) from pg_trigger where tgrelid='public.digital_channels'::regclass and not tgisinternal),1::bigint,'Somente um trigger de usuario');
select ok((select tgtype=19 and tgenabled='O' and tgfoid='public.set_digital_channels_updated_at()'::regprocedure from pg_trigger where tgrelid='public.digital_channels'::regclass and tgname='digital_channels_set_updated_at'),'Trigger BEFORE UPDATE ROW ativo aponta para funcao especifica');
select ok((select not prosecdef and prorettype='trigger'::regtype and proconfig=array['search_path=pg_catalog'] and pronargs=0 from pg_proc where oid='public.set_digital_channels_updated_at()'::regprocedure),'Funcao trigger INVOKER sem argumentos com search_path fixo');
select ok(not has_function_privilege('authenticated','public.set_digital_channels_updated_at()','EXECUTE') and not has_function_privilege('anon','public.set_digital_channels_updated_at()','EXECUTE'),'Funcao nao executavel diretamente por authenticated/anon');

