set local request.jwt.claims = '{"sub":"12000000-0000-4000-8000-000000000001","role":"authenticated"}';
set local role authenticated;
select is((select count(*) from public.digital_channels),0::bigint,'Membership revogado retira canais sem renovar claims');
reset role;
delete from public.user_global_roles where user_id='12000000-0000-4000-8000-000000000003';
set local request.jwt.claims = '{"sub":"12000000-0000-4000-8000-000000000003","role":"authenticated"}';
set local role authenticated;
select is((select count(*) from public.digital_channels),0::bigint,'Admin revogado nao le');
select throws_ok($$insert into public.digital_channels(organization_id,type,url) values ('22000000-0000-4000-8000-000000000001','SITE','https://example.test')$$,'42501',null,'Admin revogado nao cria');
with changed as (update public.digital_channels set location_id=null,url='https://example.test/negado' returning id) select is((select count(*) from changed),0::bigint,'Admin revogado nao altera');
reset role;
select * from finish();
rollback;
